// ---- 3D models (3D view) built from the page primitives box / cyl / hcyl / sphere / sub
window.XPM=(function(){const M={},WH='#f4f5f7',GY='#94a3b8',DK='#1f2937',RD='#b91c1c',GL='#2a3a52';
  const CC=['#2f7fd8','#e85d4a','#f2a33a','#2fae6a','#7b5cc9','#94a3b8','#14b8a6'];
  M.ship=(A,o)=>{o=o||{};const L=o.L||80,hull=o.hull||'#1f3b63';
    box(0,0,0,L,16,4,RD);box(0,0,4,L,16,6,hull);box(L/2+2,0,2,6,10,8,hull);
    const n=Math.floor((L-26)/9);for(let i=0;i<n;i++)for(let t=0;t<(o.t||2)+(i%3===1?1:0);t++)box(-L/2+20+i*9,0,10+t*5,8,14,5,CC[(i*3+t)%CC.length]);
    box(-L/2+8,0,10,10,14,14,WH);box(-L/2+8,0,24,12,16,1.5,GY);cyl(-L/2+5,0,25,2.2,8,o.fun||'#e85d4a',10);box(-L/2+12.2,0,18,.6,12,3,GL);};
  M.ship3=A=>M.ship(A,{L:96,t:3});
  M.greenship=A=>{M.ship(A,{L:84,hull:'#166534',fun:'#22c55e'});cyl(-28,8,10,3,8,'#e2e8f0',12);sphere(-28,8,19,2.2,'#22c55e',8);};
  M.crane=A=>{[-10,10].forEach(x=>[-8,8].forEach(y=>box(x,y,0,3,3,46,'#f2b134')));box(0,0,40,26,20,4,'#f2b134');box(14,0,46,64,6,4,'#f2b134');box(-14,0,46,10,10,8,GY);
    box(24,0,40,8,6,4,DK);cyl(24,0,26,.4,14,DK,6);box(24,0,22,10,7,5,CC[0]);};
  M.stack=A=>{for(let i=0;i<4;i++)for(let j=0;j<2;j++)for(let t=0;t<3-(i+j)%2;t++)box(-15+i*10,-6+j*12,t*7,9,11,7,CC[(i*2+j+t*3)%CC.length]);};
  M.tanks=A=>{[[-14,0],[0,6],[14,0]].forEach(([x,y],i)=>{cyl(x,y,0,6,24,'#e2e8f0',14);cyl(x,y,24,6,3,'#cbd5e1',14,1.2);box(x,y-6.2,10,6,.6,4,'#22c55e');});hcyl('x',0,-8,6,1.4,40,GY,8);};
  M.barge=A=>{box(0,0,0,56,18,6,'#334155');box(0,0,6,56,18,2,'#64748b');[-14,4].forEach(x=>hcyl('x',x,0,12,6,16,'#e2e8f0',12));box(22,0,8,8,10,10,WH);cyl(24,0,18,1.2,6,'#22c55e',8);};
  M.turbine=A=>{cyl(0,0,0,2.4,60,'#f1f5f9',12,1.4);box(0,0,60,6,4,4,WH);[0,2.094,4.189].forEach(a=>box(0+Math.cos(a)*14,-3,62+Math.sin(a)*14,Math.abs(Math.cos(a))*26+2,1,Math.abs(Math.sin(a))*26+2,WH));};
  M.cert=A=>{box(0,0,0,40,4,30,WH,'#e2e8f0');[8,14,20].forEach(z=>box(-4,-2.2,z,24,.6,1.6,GY));sphere(12,-3,6,5,'#22c55e',10);};
  M.island=A=>{cyl(0,0,0,26,3,'#f2d9a0',18);[[-8,4],[8,-4]].forEach(([x,y])=>{cyl(x,y,3,1.2,22,'#8b5a2b',8);sphere(x,y,26,6,'#2fae6a',10);});};
  M.lighthouse=A=>{cyl(0,0,0,10,4,GY,14);cyl(0,0,4,6,40,'#f8fafc',14,4);box(0,-5,22,10,.6,8,RD);cyl(0,0,44,5,6,'#fde68a',12);cyl(0,0,50,5.5,3,RD,12,1);};
  M.xproot=A=>{sub(a=>M.ship(a,{L:80}),A,10,14,0,.7,0);sub(M.crane,A,-26,-10,0,.7,0);};
  return M;})();

