// ---- harbour engine (canvas 2D, no libraries). Drawing units 2360 x 1078 = 2 x the overlay.
window.XPF_HARBOUR=function(cv,opt){opt=opt||{};
const W=2360,H=1078,HZ=470,QY=640,K=cv.width/W;
const ZX=[[98,626],[644,1172],[1188,1716],[1734,2262]];
const CC=['#2f7fd8','#e85d4a','#f2a33a','#2fae6a','#7b5cc9','#8fa3b8','#14b8a6','#f97316','#e2e8f0'];
const hash=n=>{const x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x);};
const ctx=cv.getContext('2d');
function shade(h,f){const n=parseInt(h.slice(1),16);let r=n>>16,g=n>>8&255,b=n&255;const m=v=>Math.max(0,Math.min(255,Math.round(f>1?v+(255-v)*(f-1):v*f)));return `rgb(${m(r)},${m(g)},${m(b)})`;}
function poly(c,pts,fill,stroke,lw){c.beginPath();pts.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.closePath();if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.lineWidth=lw||1;c.stroke();}}
function rect(c,x,y,w,h,f){c.fillStyle=f;c.fillRect(x,y,w,h);}
// container: front face + top, pseudo-3D
function box(c,x,y,w,h,col){rect(c,x,y,w,h,col);poly(c,[[x,y],[x+6,y-5],[x+w+6,y-5],[x+w,y]],shade(col,1.25));poly(c,[[x+w,y],[x+w+6,y-5],[x+w+6,y+h-5],[x+w,y+h]],shade(col,.72));
  c.strokeStyle='rgba(0,0,0,.14)';c.lineWidth=1;for(let i=1;i<5;i++){c.beginPath();c.moveTo(x+i*w/5,y+2);c.lineTo(x+i*w/5,y+h-2);c.stroke();}}
function stack(c,x,y,cols,tiers,seed){for(let i=0;i<cols;i++){const n=tiers-Math.floor(hash(seed+i)*2);for(let t=0;t<n;t++)box(c,x+i*38,y-(t+1)*19,36,19,CC[Math.floor(hash(seed*3+i*7+t)*CC.length)]);}}
// feeder ship, waterline at y, bow to the right (dir 1) or left (-1)
function ship(c,x,y,L,o){o=o||{};c.save();c.translate(x,y);if(o.dir===-1){c.scale(-1,1);}
  const h=L*.13,hull=o.hull||'#1f3b63';
  poly(c,[[0,-h],[L*.94,-h],[L*1.02,-h*1.35],[L*.97,0],[L*.06,0],[-L*.01,-h*.4]],hull);
  poly(c,[[L*.06,0],[L*.97,0],[L*.985,-h*.28],[L*.02,-h*.28]],'#b91c1c');
  rect(c,0,-h-2,L*.95,3,'rgba(255,255,255,.55)');
  // deck containers
  const bw=L*.052,bh=bw*.52;let i=0;for(let xx=L*.2;xx<L*.9-bw;xx+=bw+1,i++){const n=(o.tiers||3)-Math.floor(hash(i+(o.seed||0))*2);for(let t=0;t<n;t++){const col=CC[Math.floor(hash(i*5+t*11+(o.seed||0))*7)];rect(c,xx,-h-(t+1)*bh,bw,bh-1,col);rect(c,xx,-h-(t+1)*bh,bw,2,shade(col,1.2));}}
  // bridge and funnel aft
  rect(c,L*.05,-h-L*.16,L*.12,L*.16,'#f4f5f7');rect(c,L*.04,-h-L*.17,L*.15,L*.02,'#cbd5e1');
  for(let k=0;k<3;k++)rect(c,L*.065,-h-L*.14+k*L*.045,L*.09,L*.016,'#334155');
  rect(c,L*.075,-h-L*.23,L*.05,L*.06,o.fun||'#e85d4a');rect(c,L*.075,-h-L*.23,L*.05,L*.012,'#1f2937');
  if(o.green){c.fillStyle='#22c55e';c.beginPath();c.ellipse(L*.6,-h*.55,L*.035,h*.22,0,0,Math.PI*2);c.fill();rect(c,L*.3,-h*.62,L*.22,h*.14,'rgba(255,255,255,.7)');}
  c.restore();}
function wake(c,x,y,L,dir,t){c.strokeStyle='rgba(255,255,255,.55)';c.lineWidth=2;for(let k=0;k<3;k++){const off=((t*40+k*30)%90);c.beginPath();const sx=dir===1?x-off:x+L+off;c.moveTo(sx,y+3+k*3);c.lineTo(sx+(dir===1?-40:40),y+6+k*4);c.stroke();}}
function palm(c,x,y,s){c.strokeStyle='#8b5a2b';c.lineWidth=5*s;c.beginPath();c.moveTo(x,y);c.quadraticCurveTo(x+8*s,y-40*s,x+4*s,y-70*s);c.stroke();c.fillStyle='#2f9e57';
  for(let a=0;a<6;a++){c.save();c.translate(x+4*s,y-70*s);c.rotate(-Math.PI/2+(a-2.5)*.55);c.beginPath();c.ellipse(20*s,0,22*s,5*s,0,0,Math.PI*2);c.fill();c.restore();}}
function tank(c,x,y,r,h){const g=c.createLinearGradient(x-r,0,x+r,0);g.addColorStop(0,'#cbd5e1');g.addColorStop(.45,'#f8fafc');g.addColorStop(1,'#94a3b8');c.fillStyle=g;c.fillRect(x-r,y-h,2*r,h);
  c.fillStyle='#e2e8f0';c.beginPath();c.ellipse(x,y-h,r,r*.28,0,0,Math.PI*2);c.fill();c.fillStyle='#22c55e';c.fillRect(x-r,y-h*.55,2*r,h*.1);
  c.fillStyle='#16a34a';c.beginPath();c.ellipse(x,y-h*.3,r*.22,r*.12,-.6,0,Math.PI*2);c.fill();}

// ---------- static layer
const bg=document.createElement('canvas');bg.width=cv.width;bg.height=cv.height;const b=bg.getContext('2d');b.setTransform(K,0,0,K,0,0);
(function(){
  let g=b.createLinearGradient(0,0,0,HZ);g.addColorStop(0,'#cfe6fb');g.addColorStop(1,'#f3f8fd');b.fillStyle=g;b.fillRect(0,0,W,HZ);
  b.fillStyle='rgba(255,236,190,.7)';b.beginPath();b.arc(1900,180,46,0,Math.PI*2);b.fill();
  // far backdrop per zone
  // 1 Asia-Pacific hub: city towers
  for(let i=0;i<14;i++){const x=110+i*36+hash(i)*10,w=24+hash(i+3)*16,h=80+hash(i+9)*150;rect(b,x,HZ-h,w,h,shade('#9fb4cc',.9+hash(i+5)*.2));
    for(let y=HZ-h+10;y<HZ-8;y+=12)rect(b,x+4,y,w-8,4,'rgba(255,255,255,.35)');}
  // 2 Middle East & ISC: dunes and low buildings
  b.fillStyle='#ecd9b0';b.beginPath();b.moveTo(644,HZ);for(let x=644;x<=1172;x+=8)b.lineTo(x,HZ-40-Math.sin(x/60)*18-Math.sin(x/23)*6);b.lineTo(1172,HZ);b.fill();
  for(let i=0;i<9;i++){const x=670+i*56,h=40+hash(i+20)*60;rect(b,x,HZ-h,40,h,'#e6cfa2');rect(b,x,HZ-h,40,5,'#d4b98a');for(let y=HZ-h+14;y<HZ-8;y+=14)rect(b,x+8,y,24,5,'rgba(120,90,50,.25)');}
  rect(b,1110,HZ-170,10,170,'#d4b98a');rect(b,1102,HZ-180,26,12,'#c9a971');
  // 3 Europe & Mediterranean: green hills, terracotta houses, lighthouse
  b.fillStyle='#b9d7a8';b.beginPath();b.moveTo(1188,HZ);for(let x=1188;x<=1716;x+=8)b.lineTo(x,HZ-70-Math.sin((x-1188)/90)*40);b.lineTo(1716,HZ);b.fill();
  for(let i=0;i<16;i++){const x=1205+hash(i+40)*470,y=HZ-20-hash(i+41)*70,w=26,h=20;rect(b,x,y-h,w,h,'#f6efe3');poly(b,[[x-3,y-h],[x+w/2,y-h-12],[x+w+3,y-h]],'#c2603d');}
  rect(b,1660,HZ-150,22,150,'#f8fafc');for(let k=0;k<3;k++)rect(b,1660,HZ-140+k*45,22,14,'#c2603d');rect(b,1656,HZ-166,30,16,'#fde68a');
  // 4 Green methanol: soft green hills
  b.fillStyle='#bfe3c4';b.beginPath();b.moveTo(1734,HZ);for(let x=1734;x<=2300;x+=8)b.lineTo(x,HZ-50-Math.sin((x-1734)/110)*36);b.lineTo(2360,HZ);b.lineTo(2360,HZ);b.fill();
  // quay land band
  const land=['#d7dde4','#e5d6b8','#d9dee2','#d5e4d2'];
  rect(b,0,HZ,W,QY-HZ,'#d7dde4');ZX.forEach(([x0,x1],i)=>{g=b.createLinearGradient(0,HZ,0,QY);g.addColorStop(0,shade(land[i],1.04));g.addColorStop(1,shade(land[i],.94));b.fillStyle=g;b.fillRect(x0-9,HZ,x1-x0+18,QY-HZ);});
  for(let x=0;x<W;x+=60)rect(b,x,QY-30,30,3,'rgba(255,255,255,.6)');
  rect(b,0,QY-6,W,8,'#7c8794');rect(b,0,QY+2,W,6,'#4b5563');for(let x=20;x<W;x+=90)rect(b,x,QY-12,10,8,'#374151');
  // container yards
  stack(b,120,QY-48,5,3,1);stack(b,330,QY-110,6,4,2);stack(b,150,QY-150,4,2,9);
  stack(b,680,QY-60,4,2,3);stack(b,860,QY-120,5,3,4);
  stack(b,1220,QY-56,5,3,5);stack(b,1420,QY-118,5,3,6);
  stack(b,1760,QY-56,3,2,7);
  // warehouses (zone 2 and 3)
  [[990,QY-150,150,70,'#cfd6dd'],[1560,QY-150,130,64,'#d6dbe0']].forEach(([x,y,w,h,c])=>{rect(b,x,y,w,h,c);poly(b,[[x-6,y],[x+w/2,y-18],[x+w+6,y]],'#94a3b8');for(let k=0;k<4;k++)rect(b,x+12+k*(w-24)/4,y+h-30,(w-24)/4-10,30,'#64748b');});
  palm(b,700,QY-20,1.1);palm(b,760,QY-8,.85);palm(b,1150,QY-22,1);
  // methanol tank farm and bunkering jetty (zone 4)
  [[1900,QY-34,40,120],[1995,QY-40,40,140],[2090,QY-34,40,120],[2190,QY-40,34,100]].forEach(([x,y,r,h])=>tank(b,x,y,r,h));
  b.strokeStyle='#64748b';b.lineWidth=5;b.beginPath();b.moveTo(1860,QY-60);b.lineTo(2230,QY-60);b.stroke();
  // sea
  g=b.createLinearGradient(0,QY,0,H);g.addColorStop(0,'#6fb3d8');g.addColorStop(1,'#2e6f9e');b.fillStyle=g;b.fillRect(0,QY+8,W,H-QY);
  // green corridor lane marker (zone 4)
  b.setLineDash([16,12]);b.strokeStyle='rgba(134,239,172,.8)';b.lineWidth=4;b.beginPath();b.moveTo(1740,1010);b.bezierCurveTo(1900,900,2100,1040,2300,930);b.stroke();b.setLineDash([]);
})();

// ---------- moving parts
const lanes=[{y:860,dir:1,v:26,ships:[{x:200,L:330,s:3},{x:1250,L:300,s:8}]},{y:1000,dir:-1,v:20,ships:[{x:600,L:380,s:5},{x:1700,L:340,s:11,green:1}]}];
const berths=[{x:150,L:430,s:21},{x:690,L:410,s:22},{x:1230,L:420,s:23},{x:1780,L:400,s:24,green:1}];
const cranes=[[250,0],[455,1.3],[790,.6],[995,2.1],[1335,1.7],[1540,.2]];
const turbines=[[1800,HZ-60,110],[2010,HZ-90,130],[2240,HZ-70,115]];
function crane(c,x,t,ph){const top=QY-330,yel='#f2b134',dk='#c98a12';
  c.fillStyle=yel;[[-46,0],[46,0]].forEach(([dx])=>{c.fillRect(x+dx-6,top+40,12,QY-top-40);});c.fillRect(x-52,QY-150,104,10);c.fillRect(x-52,top+40,104,12);
  c.strokeStyle=dk;c.lineWidth=4;c.beginPath();c.moveTo(x-46,top+52);c.lineTo(x+46,QY-150);c.moveTo(x+46,top+52);c.lineTo(x-46,QY-150);c.stroke();
  c.fillStyle=yel;c.fillRect(x-80,top+20,250,14);c.fillStyle='#94a3b8';c.fillRect(x-80,top+8,34,26);
  c.strokeStyle=dk;c.lineWidth=2.5;c.beginPath();c.moveTo(x,top-30);c.lineTo(x-74,top+20);c.moveTo(x,top-30);c.lineTo(x+160,top+20);c.stroke();c.fillStyle=yel;c.fillRect(x-6,top-30,12,60);
  const u=(Math.sin(t*.35+ph)+1)/2,tx=x+36+u*118,dy=40+((Math.sin(t*.7+ph*2)+1)/2)*(QY-top-40);
  c.fillStyle='#334155';c.fillRect(tx-14,top+16,28,22);c.strokeStyle='#1f2937';c.lineWidth=1.5;c.beginPath();c.moveTo(tx-6,top+38);c.lineTo(tx-6,top+dy);c.moveTo(tx+6,top+38);c.lineTo(tx+6,top+dy);c.stroke();
  c.fillStyle='#1f2937';c.fillRect(tx-22,top+dy,44,5);if(Math.sin(t*.7+ph*2)>-.2){const col=CC[Math.floor(hash(Math.floor(t*.7/6.283+ph))*7)];rect(c,tx-20,top+dy+5,40,20,col);}}
function turbine(c,x,y,h,t){c.fillStyle='#f8fafc';poly(c,[[x-5,y],[x+5,y],[x+2.5,y-h],[x-2.5,y-h]],'#f8fafc','rgba(0,0,0,.08)');
  c.save();c.translate(x,y-h);c.rotate(t*1.1+x);for(let k=0;k<3;k++){c.rotate(2.094);poly(c,[[-2.5,0],[2.5,0],[1,-h*.5],[-1,-h*.5]],'#ffffff','rgba(0,0,0,.12)');}c.restore();c.fillStyle='#e2e8f0';c.beginPath();c.arc(x,y-h,4,0,Math.PI*2);c.fill();}
let T=0,playing=true;
function frame(dt){if(playing)T+=dt;const t=T;ctx.setTransform(1,0,0,1,0,0);ctx.drawImage(bg,0,0);ctx.setTransform(K,0,0,K,0,0);
  // clouds
  ctx.fillStyle='rgba(255,255,255,.85)';for(let i=0;i<5;i++){const x=((i*530+t*8)%(W+300))-150,y=70+i%3*50;ctx.beginPath();ctx.ellipse(x,y,70,18,0,0,Math.PI*2);ctx.ellipse(x+40,y-12,44,18,0,0,Math.PI*2);ctx.fill();}
  turbines.forEach(([x,y,h])=>turbine(ctx,x,y,h,t));
  // waves
  ctx.strokeStyle='rgba(255,255,255,.28)';ctx.lineWidth=2;for(let r=0;r<9;r++){const y=QY+40+r*46,o=(t*(14+r*2))%120;ctx.beginPath();for(let x=-120+o+(r%2)*60;x<W;x+=120){ctx.moveTo(x,y);ctx.quadraticCurveTo(x+15,y-5,x+30,y);}ctx.stroke();}
  // berthed ships, bunker barge, cranes
  berths.forEach(s=>ship(ctx,s.x,QY+92,s.L,{seed:s.s,hull:s.green?'#166534':'#1f3b63',fun:s.green?'#22c55e':'#e85d4a',green:s.green,tiers:3}));
  ctx.fillStyle='#334155';ctx.fillRect(2200,QY+80,120,22);ctx.fillStyle='#e2e8f0';ctx.fillRect(2212,QY+64,40,16);ctx.fillRect(2262,QY+64,40,16);
  ctx.strokeStyle='#22c55e';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(2215,QY+66);ctx.quadraticCurveTo(2190,QY+40+Math.sin(t*2)*3,2170,QY+30);ctx.stroke();
  cranes.forEach(([x,ph])=>crane(ctx,x,t,ph));
  ctx.fillStyle='#64748b';ctx.fillRect(2120,QY-200,12,200);ctx.strokeStyle='#22c55e';ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(2126,QY-196);ctx.lineTo(2060+Math.sin(t*.4)*8,QY-120);ctx.lineTo(2040,QY+30);ctx.stroke();
  // sailing feeders with wakes
  lanes.forEach(l=>l.ships.forEach(s=>{const span=W+800;let x=((s.x+l.dir*l.v*t)%span+span)%span-400;wake(ctx,x,l.y,s.L,l.dir,t);ship(ctx,x,l.y,s.L,{dir:l.dir,seed:s.s,hull:s.green?'#166534':'#24456f',fun:s.green?'#22c55e':'#e85d4a',green:s.green,tiers:2});}));
  opt.onFrame&&opt.onFrame();}
let last=performance.now(),first=true,acc=0;
function loop(ts){if(!cv.isConnected&&!first)return;const dt=Math.min(.08,(ts-last)/1000);last=ts;acc+=dt;
  if(first||(!document.hidden&&acc>=1/30)){frame(acc);acc=0;if(first){first=false;opt.onFirst&&opt.onFirst();}}requestAnimationFrame(loop);}
requestAnimationFrame(loop);
return {pause:p=>{playing=!p;},isPlaying:()=>playing};
};

