   vis.forEach(s=>{if(s.i===focus||(ST.sel!=null))return;s.legs.forEach((L,j)=>{if(!s.sea||s.sea[j]===undefined||(s.fail&&s.fail[j]))return;stroke(L,col(s),1.3,focus!=null?.12:.55);});});
