     const scr=L=>{const o=[];let cur=[];for(const p of L){const q=rot(p);if(q[2]<=.02){if(cur.length>1)o.push(cur);cur=[];continue;}cur.push([cx+q[0]*r,cy-q[1]*r]);}if(cur.length>1)o.push(cur);return o;};
