     const GRID={},gk=(x,y)=>((x/5)|0)+','+((y/5)|0),busy=(x,y)=>{const X=(x/5)|0,Y=(y/5)|0;for(let a=-1;a<=1;a++)for(let b=-1;b<=1;b++)if(GRID[(X+a)+','+(Y+b)])return true;return false;};
     const lane=s.legs.map(L=>{const parts=scr(L);for(let k=0;k<6;k++){const d=3.5+k*4.5;let n=0,hit=0;parts.forEach(pl=>off(pl,d).forEach((p,i)=>{if(i%2)return;n++;if(busy(p[0],p[1]))hit++;}));if(!n||hit/n<.06||k===5){parts.forEach(pl=>off(pl,d).forEach(p=>{GRID[gk(p[0],p[1])]=1;}));return d;}}return 5;});
