       g.font='700 10px "Segoe UI",system-ui,sans-serif';const nw=num?g.measureText(num).width+8:0;g.font='600 11px "Segoe UI",system-ui,sans-serif';const tw=g.measureText(p).width+8;g.font='800 9px "Segoe UI",system-ui,sans-serif';const gw=tag?g.measureText(tag).width+8:0;
